import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

/// 1. 数据模型
class User {
  const User({required this.id, required this.name});

  final int id;
  final String name;

  factory User.fromJson(Map<String, dynamic> json) =>
      User(id: json['id'] as int, name: json['name'] as String);
}

/// 2. 模拟网络层（真实项目里换成 dio / http）
Future<List<User>> fetchUsers() async {
  await Future<void>.delayed(const Duration(seconds: 1));
  // 想观察 error 分支时，把下一行取消注释即可
  // throw Exception('网络异常');
  return const [
    User(id: 1, name: 'Alice'),
    User(id: 2, name: 'Bob'),
    User(id: 3, name: 'Carol'),
  ];
}

/// 3. AsyncNotifier：异步状态的唯一事实来源（Single Source of Truth）
class UsersNotifier extends AsyncNotifier<List<User>> {
  @override
  Future<List<User>> build() {
    // 返回值会被 Riverpod 自动包装成 AsyncValue：loading -> data / error
    // 依赖变化时 build 会自动重新执行，无需手动管理订阅
    return fetchUsers();
  }

  /// 下拉刷新：guard 会自动把异常转成 AsyncError
  Future<void> refresh() async {
    // 如果想让刷新期间保留旧列表，就不要手动置为 loading
    state = const AsyncValue.loading();
    state = await AsyncValue.guard(fetchUsers);
  }

  /// 同步修改：直接写入 AsyncData，UI 立即响应
  void remove(int id) {
    final current = state.valueOrNull;
    if (current == null) return;
    state = AsyncValue.data(
      current.where((user) => user.id != id).toList(),
    );
  }
}

/// 4. Provider 声明
final usersProvider = AsyncNotifierProvider<UsersNotifier, List<User>>(
  UsersNotifier.new,
);

/// 5. UI：watch 订阅重建，read.notifier 触发动作
class UserListPage extends ConsumerWidget {
  const UserListPage({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final usersAsync = ref.watch(usersProvider);

    return Scaffold(
      appBar: AppBar(title: const Text('用户列表')),
      body: RefreshIndicator(
        onRefresh: () => ref.read(usersProvider.notifier).refresh(),
        child: usersAsync.when(
          // 穷举三分支，漏写分支会编译报错
          loading: () => const Center(child: CircularProgressIndicator()),
          error: (err, stack) => Center(child: Text('出错了：$err')),
          data: (users) => ListView.builder(
            // 保证列表不足一屏时也能触发下拉刷新
            physics: const AlwaysScrollableScrollPhysics(),
            itemCount: users.length,
            itemBuilder: (context, index) {
              final user = users[index];
              return ListTile(
                title: Text(user.name),
                trailing: IconButton(
                  icon: const Icon(Icons.delete_outline),
                  onPressed: () =>
                      ref.read(usersProvider.notifier).remove(user.id),
                ),
              );
            },
          ),
        ),
      ),
    );
  }
}

void main() {
  // 根节点必须有 ProviderScope，否则所有 Provider 都无法解析
  runApp(const ProviderScope(child: MaterialApp(home: UserListPage())));
}

