class Counter extends AsyncNotifier<int> {
  @override
  Future<int> build() async {
    await Future<void>.delayed(const Duration(milliseconds: 50));
    return 10;
  }

  void add() {
    state = AsyncValue.data((state.valueOrNull ?? 0) + 5);
  }
}

